function e(t){return String(t).padStart(2,"0")}function g(t){if(!t)return"-";const n=new Date(t);return isNaN(n.getTime())?String(t):`${n.getFullYear()}-${e(n.getMonth()+1)}-${e(n.getDate())} ${e(n.getHours())}:${e(n.getMinutes())}:${e(n.getSeconds())}`}function s(t){const n=-t.getTimezoneOffset(),a=n>=0?"+":"-",o=e(Math.floor(Math.abs(n)/60)),r=e(Math.abs(n)%60);return`${t.getFullYear()}-${e(t.getMonth()+1)}-${e(t.getDate())}T${e(t.getHours())}:${e(t.getMinutes())}:${e(t.getSeconds())}${a}${o}:${r}`}export{s as a,g as f};
